USE [DeineDatenbank];
GO

/*
===============================================================================
Objekt       : monitor.USP_QueryStoreForcedPlans
Version      : 2.0.0
Stand        : 2026-07-15
Zweck        : Liefert erzwungene Query-Store-Pläne aus mehreren
               Quelldatenbanken mit globaler Top-N-Ausgabe und optionalem
               Referenzdatenbankfilter.
===============================================================================
*/
CREATE OR ALTER PROCEDURE [monitor].[USP_QueryStoreForcedPlans]
      @QueryStoreDatabaseNames          nvarchar(max)  = NULL
    , @QueryStoreDatabaseNamePattern    nvarchar(4000) = NULL
    , @HighImpactConfirmed              bit            = 0
    , @ReferencedDatabaseNames          nvarchar(max)  = NULL
    , @ReferencedDatabaseNamePattern    nvarchar(4000) = NULL
    , @QueryId                          bigint         = NULL
    , @NurMitFehler                     bit            = 0
    , @MitPlanXml                       bit            = 0
    , @MaxZeilen                        int            = 100
    , @MaxSqlTextZeichen                int            = 4000
    , @ResultSetArt                     varchar(16)    = 'CONSOLE'
    , @ResultTablesJson               nvarchar(max) = NULL
    , @JsonErzeugen                     bit            = 0
    , @Json                             nvarchar(max)  = NULL OUTPUT
    , @PrintMeldungen                   bit            = 1
    , @Hilfe                            bit            = 0
AS
BEGIN
 SET NOCOUNT ON;SET @Json=NULL;DECLARE @Out varchar(16)=UPPER(LTRIM(RTRIM(COALESCE(@ResultSetArt,'')))),@Limit bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) WHEN @MaxZeilen>0 THEN @MaxZeilen ELSE 0 END,@Local bigint=CASE WHEN @MaxZeilen IS NULL OR @MaxZeilen=0 THEN CONVERT(bigint,9223372036854775807) WHEN @MaxZeilen<2147483647 THEN CONVERT(bigint,@MaxZeilen)+1 ELSE @MaxZeilen END;
 CREATE TABLE [#QueryStoreForcedPlans_Export]([QueryStoreDatabaseId] int,[QueryStoreDatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,[QueryId] bigint,[PlanId] bigint,[QueryHash] binary(8),[QueryPlanHash] binary(8),[ObjectId] bigint NULL,[ObjectName] nvarchar(517) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[IsForcedPlan] bit,[PlanForcingTypeDesc] nvarchar(60) COLLATE SQL_Latin1_General_CP1_CS_AS,[ForceFailureCount] bigint,[LastForceFailureReason] int,[LastForceFailureReasonDesc] nvarchar(128) COLLATE SQL_Latin1_General_CP1_CS_AS,[CountCompiles] bigint,[LastCompileStartTimeUtc] datetimeoffset,[LastExecutionTimeUtc] datetimeoffset,[EngineVersion] nvarchar(32) COLLATE SQL_Latin1_General_CP1_CS_AS,[CompatibilityLevel] smallint,[QuerySqlText] nvarchar(max) COLLATE SQL_Latin1_General_CP1_CS_AS,[QueryPlanTextFallback] nvarchar(max) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[SourceType] varchar(32) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[SourceObject] nvarchar(256) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[CapturedAtUtc] datetime2(3) NULL,[EvidenceScope] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[QuerySqlTextCharacters] bigint NULL,[QuerySqlTextBytes] bigint NULL,[QuerySqlTextIsTruncated] bit NULL,[QueryPlanStatus] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[QueryPlanCharacters] bigint NULL,[QueryPlanBytes] bigint NULL,[QueryPlan] xml NULL,[EvidenceLimit] nvarchar(1000) COLLATE SQL_Latin1_General_CP1_CS_AS NULL);
    DECLARE @TableResultRequested bit = CASE WHEN @Out = 'TABLE' THEN 1 ELSE 0 END;
    DECLARE @ConsoleResultRequested bit = CASE WHEN @Out = 'CONSOLE' THEN 1 ELSE 0 END;
    DECLARE @TableTarget sysname=NULL;
    IF @TableResultRequested=0 AND NULLIF(LTRIM(RTRIM(COALESCE(@ResultTablesJson,N''))),N'') IS NOT NULL THROW 51011,N'@ResultTablesJson ist ausschließlich mit @ResultSetArt=TABLE zulässig.',1;
    IF @TableResultRequested=1 EXEC [monitor].[InternalPrepareSingleResultTable] @ResultTablesJson=@ResultTablesJson,@ResultName=N'forcedPlans',@TargetTable=@TableTarget OUTPUT,@ThrowOnError=1;
    IF @TableResultRequested = 1 OR @ConsoleResultRequested = 1 SET @Out = 'NONE';
 IF @Hilfe=1
 BEGIN
        PRINT N'monitor.USP_QueryStoreForcedPlans';
        PRINT N'monitor.USP_QueryStoreForcedPlans inventarisiert aktuell erzwungene Query-Store-Pläne, Force-Fehler und zugehörige Metadaten in ausgewählten Quelldatenbanken. Der persistierte Status belegt weder eine künftige erfolgreiche Bindung noch die betriebliche Eignung eines Plans.';
        PRINT N'Datenbankauswahl: @QueryStoreDatabaseNames ist eine bracket-aware Pipe-Liste; NULL, leer oder nur Leerzeichen wählt alle sichtbaren Online-Benutzerdatenbanken. Alternativ dient @QueryStoreDatabaseNamePattern mit SQL-LIKE (ohne Präfix oder like:), regex: oder regexi:. Liste und Pattern sind exklusiv; Systemdatenbanken bleiben ausgeschlossen. Regex für die Quellauswahl benötigt SQL Server 2025 und Compatibility Level 170 in der Installationsdatenbank.';
        PRINT N'Referenzfilter: @ReferencedDatabaseNames prüft Plan-XML-Objektreferenzen mit einer bracket-aware Pipe-Liste; NULL lässt den Filter weg, leer ist ungültig. Alternativ dient @ReferencedDatabaseNamePattern mit LIKE, regex: oder regexi:. Regex benötigt SQL Server 2025 und Compatibility Level 170 je geprüfter Quelldatenbank. Referenzfilter und Plan-XML aktivieren QUERY_STORE_DEEP.';
        PRINT N'@HighImpactConfirmed=1 bestätigt den jeweils verwendeten QUERY_STORE_CURRENT- und gegebenenfalls QUERY_STORE_DEEP-Pfad. Eine aktive Analyseklassenrichtlinie kann eine zusätzliche Bestätigung oder Zugriffsfreigabe verlangen; die Bestätigung umgeht diese Richtlinie nicht.';
        PRINT N'Die beschriebenen fachlichen Validierungen gelten im normalen Analysepfad. @Hilfe=1 kehrt vorher zurück; SQL-Typbindung und frühe Mappingprüfungen bleiben aktiv. Ausgelassen gilt bei jedem Parameter der ausdrücklich angegebene Default.';
        PRINT N'@QueryStoreDatabaseNames nvarchar(max); Default: NULL. Ausgelassen/NULL, N'''' oder nur äußere U+0020-Leerzeichen: keine Einschränkung. Sonst bracket-aware Pipe-Liste exakter einteiliger SQL-Datenbanknamen, zum Beispiel N''[ExampleDatabase]|[OtherDatabase]''; | trennt außerhalb von [...], ]] maskiert ]. Leere Elemente, ungültige Namen und Duplikate sind INVALID_PARAMETER. Eine effektive nichtleere Liste ist exklusiv mit dem nicht-NULL Quellpattern. Ohne Filter werden sichtbare geeignete Online-Benutzerdatenbanken gewählt; Systemdatenbanken bleiben ausgeschlossen.';
        PRINT N'@QueryStoreDatabaseNamePattern nvarchar(4000); Default: NULL. ausgelassen/NULL kein Filter. Äußeres Trimmen, dann like: bedeutet SQL-LIKE-Muster, regex: regulärer Ausdruck mit Flag c (case-sensitiv), regexi: regulärer Ausdruck mit Flag i (case-insensitiv); Präfixe ohne Beachtung der Großschreibung entfernen. Ohne Präfix gilt LIKE; Rest wird nicht erneut getrimmt. Leer oder leer nach Präfix ist ungültig; exklusiv mit @QueryStoreDatabaseNames. REGEX/REGEXI laufen in der Installationsdatenbank und benötigen SQL Server 2025 plus CL170 dort; Syntax wird nicht vorab validiert.';
        PRINT N'@HighImpactConfirmed bit; Default: 0. ausgelassen/0 = nicht bestätigt. NULL ist im Datenbankhelfer INVALID_PARAMETER. 1 bestätigt nur ein aktiviertes Gruppengate: QUERY_STORE_CURRENT hat kein Gruppengate, QUERY_STORE_DEEP verwendet es. Die Bestätigung ändert keinen Scope und erteilt weder SQL-Berechtigung noch Gruppenmitgliedschaft. Als bit 0 oder 1 übergeben; SQL-Typkonvertierung kann andere numerische Nichtnullwerte auf 1 abbilden.';
        PRINT N'@ReferencedDatabaseNames nvarchar(max); Default: NULL. ausgelassen/NULL kein Showplan-Referenzfilter. Sonst nichtleere bracket-aware Pipe-Liste einteiliger SQL-Namen; | trennt außerhalb von [...], ]] maskiert ]. Leerwert/Leerzeichen ungültig. Teil 1 muss nicht NULL, Teil 2 NULL und LEN(Teil 1) höchstens 128 sein; Teile 3/4 werden nicht gesondert geprüft. Gültige Namen werden mit expliziter Framework-Collation SQL_Latin1_General_CP1_CS_AS verglichen. Duplikate sind erlaubt; EXISTS vervielfacht keine Zeilen. Exklusiv mit @ReferencedDatabaseNamePattern; setzt QUERY_STORE_DEEP voraus.';
        PRINT N'@ReferencedDatabaseNamePattern nvarchar(4000); Default: NULL. ausgelassen/NULL kein Filter. Äußeres Trimmen, dann like: bedeutet SQL-LIKE-Muster, regex: regulärer Ausdruck mit Flag c (case-sensitiv), regexi: regulärer Ausdruck mit Flag i (case-insensitiv); Präfixe ohne Beachtung der Großschreibung. Ohne Präfix LIKE; Rest wird nicht erneut getrimmt; leer/leer nach Präfix ungültig. Exklusiv mit @ReferencedDatabaseNames; setzt QUERY_STORE_DEEP voraus. REGEX/REGEXI laufen je Quelldatenbank und benötigen SQL Server 2025 sowie CL170 dort; Syntax wird nicht vorab validiert.';
        PRINT N'@QueryId bigint; Default: NULL. Ausgelassen/NULL: kein Query-ID-Filter. Einen ganzzahligen bigint-Wert von -9223372036854775808 bis 9223372036854775807 übergeben; keine zusätzliche Positivitäts- oder Existenzprüfung. Exakter Vergleich je Quelle; Query-IDs sind quellenspezifisch.';
        PRINT N'@NurMitFehler bit; Default: 0. Weglassen ergibt 0. Numerisches 0 wird zu 0, jeder numerische Nichtnullwert zu 1. 0 zeigt alle als erzwungen markierten Pläne; 1 beschränkt auf ForceFailureCount > 0 oder LastForceFailureReason <> 0. NULL ist nicht als 0 behandelt und lässt durch SQL-NULL-Semantik praktisch nur Zeilen mit erfüllter Fehlerbedingung passieren.';
        PRINT N'@MitPlanXml bit; Default: 0. Ausgelassen/0: keine exportierte Plan-XML und kein XML-Parsing; QueryPlanStatus ist NOT_REQUESTED. 1 aktiviert Ausgabe und Parsing des gespeicherten historischen Query-Store-Plans für alle lokal gesammelten Kandidaten vor dem globalen Limit und löst Deep aus; kein aktueller Laufzeitplan. NULL aktiviert weder Ausgabe/Parsing noch allein Deep, hat aber PENDING statt NOT_REQUESTED. Referenzfilter können Plan-XML unabhängig vom Ausgabeschalter lesen. Ungültiges XML bleibt als Rohtext mit Fehler-/Partialhinweis erhalten. Als bit 0/1 übergeben; konvertierbare numerische Werte ungleich 0 werden 1.';
        PRINT N'@MaxZeilen int; Default: 100. Weglassen ergibt globales Exportlimit 100. NULL oder 0 bedeutet unbegrenzt; positive Werte sind das globale Ausgabelimit. Negative Werte sind im normalen Aufruf ungültig. Je Datenbank wird lokal mit N+1 (bei int-Maximum höchstens int-Maximum) gelesen und die gemeinsame Menge anschließend global begrenzt; es handelt sich nicht um ein globales TOP im Quellzugriff. Ein normalisiertes Limit über 1000, auch NULL/0, aktiviert den Deep-Check. Als ganze Zahl im SQL-int-Bereich bis 2147483647 übergeben. Lokales und globales Ranking stellen Pläne mit LastForceFailureReason ungleich 0 voran, danach LastExecutionTimeUtc absteigend. ForceFailureCount ist kein Sortierschlüssel; Sortties garantieren keine bestimmte Auswahl. Textprojektion, XML-Parsing, Warnungen und Zähler betreffen alle lokalen Kandidaten vor dem globalen Limit.';
        PRINT N'@MaxSqlTextZeichen int; Default: 4000. Weglassen begrenzt den projizierten Query-Text auf 4000 Zeichen. NULL oder 0 bedeutet unbegrenzt; ein positiver Wert ist die Unicode-sichere Zeichengrenze. Negative Werte sind im normalen Aufruf ungültig. Bei Kürzung kann abhängig von @PrintMeldungen eine Truncationwarnung erscheinen; die Grenze beschränkt die Ausgabeprojektion, nicht die Quellabfrage. Als ganze Zahl im SQL-int-Bereich bis 2147483647 übergeben. SC-Collation zählt ein Surrogatpaar als ein Zeichen; keine Graphemzählung, keine Kürzung des Plan-XML.';
        PRINT N'@ResultSetArt varchar(16); Default: ''CONSOLE''. Ausgelassen: CONSOLE. Nach U+0020-Trim/Großschreibung sind genau vier Werte erlaubt: RAW liefert drei Resultsets (Metadaten, forcedPlans, Warnungen); CONSOLE liefert die fachliche Exportmenge mit Ergebnislabel oder bei Leere eine Hinweiszeile, ohne zusätzliche Metadaten-/Warnungsgrids; TABLE schreibt nur forcedPlans ins geprüfte lokale Temp-Ziel; NONE unterdrückt normale Fachresultsets. JSON ist unabhängig. NULL, leer, nur Leerzeichen und andere Werte sind im normalen Analysepfad ungültig. Der TABLE-Preflight liegt vor Hilfe und Fachvalidierung. Der Eingabewert unterliegt der varchar(16)-Bindungsbreite.';
        PRINT N'@ResultTablesJson nvarchar(max); Default: NULL. außerhalb TABLE nur NULL, leer oder Leerzeichen zulässig; anderer nichtleerer Inhalt wirft 51011. Bei TABLE nichtleeres JSON-Objekt mit genau dem Schlüssel forcedPlans und einem Ziel. Ziel: vorhandene, leere lokale #Temp-Tabelle (kein ##), maximal 116 Zeichen und genau eine beliebige Seed-Spalte; das volle Ergebnis-Schema muss nicht angelegt werden. Fehlendes/ungültiges Mapping/Ziel wird im frühen Preflight abgelehnt; leerer Wert ist in TABLE ungültig. Schlüssel binär exakt und ohne Duplikate; Ziele dürfen weder ## noch das reservierte #Monitor-Präfix verwenden. Ein Seed-Datensatz ist nicht zulässig; der Writer ersetzt die Seed-Struktur durch das Ergebnisschema.';
        PRINT N'@JsonErzeugen bit; Default: 0. Weglassen ergibt 0; numerisches 0 wird 0, jeder numerische Nichtnullwert wird zu 1. NULL aktiviert JSON nicht. Bei 1 wird das JSON-Objekt mit meta, forcedPlans und warnings erzeugt; dies ist unabhängig von @ResultSetArt.';
        PRINT N'@Json nvarchar(max) OUTPUT; Default: NULL. OUTPUT-Parameter. Zum Empfang nvarchar(max)-Variable als @Json=@Variable OUTPUT binden. Beim Eintritt auf NULL gesetzt und nur bei @JsonErzeugen=1 gefüllt; bei Hilfe bleibt es NULL. Ausgelassen gilt der Vorgabewert, das Ergebnis ist dann nicht abrufbar. Leerwert als Eingabe wird nicht ausgewertet. Bei ungefangenem THROW besteht keine Zusage einer OUTPUT-Rückübertragung.';
        PRINT N'@PrintMeldungen bit; Default: 1. ausgelassen lässt Meldungen zu. 1 erlaubt Fehlerhinweise und die Truncationwarnung; 0 unterdrückt diese Meldungen. NULL unterdrückt die Truncationwarnung und erfüllt die direkte Fehlerausgabebedingung nicht. Status, Resultsets und Datenmenge bleiben davon unberührt. Als bit 0 oder 1 übergeben; SQL-Typkonvertierung kann andere numerische Nichtnullwerte auf 1 abbilden.';
        PRINT N'@Hilfe bit; Default: 0. ausgelassen/NULL führt normal aus. Nur 1 druckt die Hilfe und beendet vor normaler Parameter- und Datenvalidierung. Rohe SQL-Bindung und früher TABLE-Mapping-Preflight bleiben aktiv und können vorher scheitern; @Json wurde beim Eintritt geleert. Als bit 0 oder 1 übergeben; SQL-Typkonvertierung kann andere numerische Nichtnullwerte auf 1 abbilden.';
        PRINT N'EXEC [monitor].[USP_QueryStoreForcedPlans] @Hilfe=1;';
        PRINT N'EXEC [monitor].[USP_QueryStoreForcedPlans] @QueryStoreDatabaseNames=N''[ExampleDatabase]'', @ResultSetArt=''RAW'';';
        PRINT N'DECLARE @ExampleJson nvarchar(max); EXEC [monitor].[USP_QueryStoreForcedPlans] @QueryStoreDatabaseNames=N''[ExampleDatabase]'', @ResultSetArt=''NONE'', @JsonErzeugen=1, @Json=@ExampleJson OUTPUT; SELECT @ExampleJson AS [Json];';
        PRINT N'CREATE TABLE [#QueryStoreForcedPlans_HelpExample]([Seed] int NULL);
BEGIN TRY
 EXEC [monitor].[USP_QueryStoreForcedPlans] @QueryStoreDatabaseNames=N''[ExampleDatabase]'', @ResultSetArt=''TABLE'', @ResultTablesJson=N''{"forcedPlans":"#QueryStoreForcedPlans_HelpExample"}'';
 SELECT * FROM [#QueryStoreForcedPlans_HelpExample];
 DROP TABLE IF EXISTS [#QueryStoreForcedPlans_HelpExample];
END TRY
BEGIN CATCH
 DROP TABLE IF EXISTS [#QueryStoreForcedPlans_HelpExample];
 THROW;
END CATCH;';
  RETURN;
 END;
 DECLARE @Now datetime2(3)=SYSUTCDATETIME(),@Status varchar(40)='AVAILABLE',@Partial bit=0,@Error nvarchar(2048)=NULL,@Cross bit=0,@Allowed bit=1,@Db sysname,@Compat tinyint,@Sql nvarchar(max),@Count bigint=0,@HasMore bit=0,@Msg nvarchar(2048),@RefMode varchar(8),@RefValue nvarchar(4000),@RefFlags varchar(8),@RefValid bit,@RefPredicate nvarchar(max)=N'';
 SELECT @RefMode=[PatternMode],@RefValue=[PatternValue],@RefFlags=[RegexFlags],@RefValid=[IsValid] FROM [monitor].[TVF_ParsePattern](@ReferencedDatabaseNamePattern);
 CREATE TABLE [#QueryStoreForcedPlans_DatabaseCandidates]([DatabaseId] int NOT NULL,[DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL,[StateDesc] nvarchar(60) COLLATE SQL_Latin1_General_CP1_CS_AS,[UserAccessDesc] nvarchar(60) COLLATE SQL_Latin1_General_CP1_CS_AS,[IsReadOnly] bit,[CompatibilityLevel] tinyint,[CollationName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS,[RecoveryModelDesc] nvarchar(60) COLLATE SQL_Latin1_General_CP1_CS_AS,[IsSystemDatabase] bit,[RequestedOrdinal] int);
 CREATE TABLE [#QueryStoreForcedPlans_Result]([QueryStoreDatabaseId] int,[QueryStoreDatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS,[QueryId] bigint,[PlanId] bigint,[QueryHash] binary(8),[QueryPlanHash] binary(8),[ObjectId] bigint NULL,[ObjectName] nvarchar(517) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[IsForcedPlan] bit,[PlanForcingTypeDesc] nvarchar(60) COLLATE SQL_Latin1_General_CP1_CS_AS,[ForceFailureCount] bigint,[LastForceFailureReason] int,[LastForceFailureReasonDesc] nvarchar(128) COLLATE SQL_Latin1_General_CP1_CS_AS,[CountCompiles] bigint,[LastCompileStartTimeUtc] datetimeoffset,[LastExecutionTimeUtc] datetimeoffset,[EngineVersion] nvarchar(32) COLLATE SQL_Latin1_General_CP1_CS_AS,[CompatibilityLevel] smallint,[QuerySqlText] nvarchar(max) COLLATE SQL_Latin1_General_CP1_CS_AS,[QueryPlanTextFallback] nvarchar(max) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[SourceType] varchar(32) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[SourceObject] nvarchar(256) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[CapturedAtUtc] datetime2(3) NULL,[EvidenceScope] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[QuerySqlTextCharacters] bigint NULL,[QuerySqlTextBytes] bigint NULL,[QuerySqlTextIsTruncated] bit NULL,[QueryPlanStatus] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NULL,[QueryPlanCharacters] bigint NULL,[QueryPlanBytes] bigint NULL,[QueryPlan] xml NULL,[EvidenceLimit] nvarchar(1000) COLLATE SQL_Latin1_General_CP1_CS_AS NULL);
 CREATE TABLE [#QueryStoreForcedPlans_Errors]([DatabaseName] sysname COLLATE SQL_Latin1_General_CP1_CS_AS,[StatusCode] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS,[ErrorNumber] int NULL,[ErrorMessage] nvarchar(2048) COLLATE SQL_Latin1_General_CP1_CS_AS);
 IF @MaxZeilen<0 OR @MaxSqlTextZeichen < 0 OR @Out NOT IN('RAW','CONSOLE','NONE') OR @RefValid=0 OR (@ReferencedDatabaseNames IS NOT NULL AND @ReferencedDatabaseNamePattern IS NOT NULL) OR (@ReferencedDatabaseNames IS NOT NULL AND EXISTS(SELECT 1 FROM [monitor].[TVF_ParseSqlNameList](@ReferencedDatabaseNames) WHERE [IsValid]=0)) BEGIN SET @Status='INVALID_PARAMETER';SET @Error=N'Ungültiger Parameter.';END;
 IF @Status='AVAILABLE' EXEC [monitor].[USP_PrepareDatabaseCandidates] @DatabaseNames=@QueryStoreDatabaseNames,@SystemdatenbankenEinbeziehen=0,@DatabaseNamePattern=@QueryStoreDatabaseNamePattern,@HighImpactConfirmed=@HighImpactConfirmed,@AnalysisClass='QUERY_STORE_CURRENT',@StatusCode=@Status OUTPUT,@ErrorMessage=@Error OUTPUT,@CrossDatabaseRequested=@Cross OUTPUT,@CandidateTable=N'#QueryStoreForcedPlans_DatabaseCandidates';
 IF @Status='AVAILABLE' AND (@MitPlanXml=1 OR @Limit>1000 OR @ReferencedDatabaseNames IS NOT NULL OR @ReferencedDatabaseNamePattern IS NOT NULL) EXEC [monitor].[InternalCheckAnalysisPath] @AnalysisClass='QUERY_STORE_DEEP',@HighImpactConfirmed=@HighImpactConfirmed,@StatusCode=@Status OUTPUT,@ErrorMessage=@Error OUTPUT;
 IF @ReferencedDatabaseNames IS NOT NULL SET @RefPredicate=N' AND EXISTS(SELECT 1 FROM (SELECT CONVERT(xml,[p].[query_plan]) [PlanXml]) [px] CROSS APPLY [px].[PlanXml].nodes(''declare default element namespace "http://schemas.microsoft.com/sqlserver/2004/07/showplan"; //Object[@Database]'') [n]([x]) JOIN ' + QUOTENAME((SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID())) + N'.[monitor].[TVF_ParseSqlNameList](@ReferencedNames) [rf] ON [rf].[IsValid]=1 AND [rf].[NameValue] COLLATE SQL_Latin1_General_CP1_CS_AS=PARSENAME([n].[x].value(''@Database'',''nvarchar(776)''),1) COLLATE SQL_Latin1_General_CP1_CS_AS)';
 ELSE IF @RefMode='LIKE' SET @RefPredicate=N' AND EXISTS(SELECT 1 FROM (SELECT CONVERT(xml,[p].[query_plan]) [PlanXml]) [px] CROSS APPLY [px].[PlanXml].nodes(''declare default element namespace "http://schemas.microsoft.com/sqlserver/2004/07/showplan"; //Object[@Database]'') [n]([x]) WHERE PARSENAME([n].[x].value(''@Database'',''nvarchar(776)''),1) COLLATE SQL_Latin1_General_CP1_CS_AS LIKE @RefValue COLLATE SQL_Latin1_General_CP1_CS_AS)';
 ELSE IF @RefMode IN('REGEX','REGEXI') SET @RefPredicate=N' AND EXISTS(SELECT 1 FROM (SELECT CONVERT(xml,[p].[query_plan]) [PlanXml]) [px] CROSS APPLY [px].[PlanXml].nodes(''declare default element namespace "http://schemas.microsoft.com/sqlserver/2004/07/showplan"; //Object[@Database]'') [n]([x]) WHERE REGEXP_LIKE(PARSENAME([n].[x].value(''@Database'',''nvarchar(776)''),1),@RefValue,@RefFlags))';
 SET LOCK_TIMEOUT 0;
 IF @Status='AVAILABLE' BEGIN DECLARE [c] CURSOR LOCAL FAST_FORWARD FOR SELECT [DatabaseName],[CompatibilityLevel] FROM [#QueryStoreForcedPlans_DatabaseCandidates] ORDER BY COALESCE([RequestedOrdinal],[DatabaseId]),[DatabaseId];OPEN [c];FETCH NEXT FROM [c] INTO @Db,@Compat;WHILE @@FETCH_STATUS=0 BEGIN IF @RefMode IN('REGEX','REGEXI') AND (TRY_CONVERT(int,SERVERPROPERTY(N'ProductMajorVersion'))<17 OR @Compat<170) BEGIN INSERT [#QueryStoreForcedPlans_Errors] VALUES(@Db,'UNAVAILABLE_FEATURE',NULL,N'Regex benötigt SQL Server 2025 und Compatibility Level 170.');SET @Partial=1;END ELSE BEGIN TRY SET @Sql=N'USE '+QUOTENAME(@Db)+N';IF EXISTS(SELECT 1 FROM [sys].[database_query_store_options] WITH (NOLOCK) WHERE [actual_state] IN(1,2,4)) INSERT [#QueryStoreForcedPlans_Result] ([QueryStoreDatabaseId],[QueryStoreDatabaseName],[QueryId],[PlanId],[QueryHash],[QueryPlanHash],[ObjectId],[ObjectName],[IsForcedPlan],[PlanForcingTypeDesc],[ForceFailureCount],[LastForceFailureReason],[LastForceFailureReasonDesc],[CountCompiles],[LastCompileStartTimeUtc],[LastExecutionTimeUtc],[EngineVersion],[CompatibilityLevel],[QuerySqlText],[QueryPlanTextFallback]) SELECT TOP(@TopRows) DB_ID(),(SELECT [name] FROM [master].[sys].[databases] WITH (NOLOCK) WHERE [database_id] = DB_ID()),[q].[query_id],[p].[plan_id],[q].[query_hash],[p].[query_plan_hash],[q].[object_id],CASE WHEN [q].[object_id]>0 THEN QUOTENAME([os].[name])+N''.''+QUOTENAME([oo].[name]) END,[p].[is_forced_plan],[p].[plan_forcing_type_desc],[p].[force_failure_count],[p].[last_force_failure_reason],[p].[last_force_failure_reason_desc],[p].[count_compiles],[p].[last_compile_start_time],[p].[last_execution_time],[p].[engine_version],[p].[compatibility_level],[qt].[query_sql_text],CASE WHEN @IncludePlan=1 THEN [p].[query_plan] END FROM [sys].[query_store_plan] [p] WITH (NOLOCK) JOIN [sys].[query_store_query] [q] WITH (NOLOCK) ON [q].[query_id]=[p].[query_id] JOIN [sys].[query_store_query_text] [qt] WITH (NOLOCK) ON [qt].[query_text_id]=[q].[query_text_id] LEFT JOIN [sys].[objects] [oo] WITH (NOLOCK) ON [oo].[object_id]=[q].[object_id] LEFT JOIN [sys].[schemas] [os] WITH (NOLOCK) ON [os].[schema_id]=[oo].[schema_id] WHERE [p].[is_forced_plan]=1 AND (@QueryId IS NULL OR [q].[query_id]=@QueryId) AND (@OnlyErrors=0 OR [p].[force_failure_count]>0 OR [p].[last_force_failure_reason]<>0)'+@RefPredicate+N' ORDER BY CASE WHEN [p].[last_force_failure_reason]<>0 THEN 0 ELSE 1 END,[p].[last_execution_time] DESC;';EXEC [sys].[sp_executesql] @Sql,N'@TopRows bigint,@QueryId bigint,@OnlyErrors bit,@IncludePlan bit,@ReferencedNames nvarchar(max),@RefValue nvarchar(4000),@RefFlags varchar(8)',@Local,@QueryId,@NurMitFehler,@MitPlanXml,@ReferencedDatabaseNames,@RefValue,@RefFlags;END TRY BEGIN CATCH INSERT [#QueryStoreForcedPlans_Errors] VALUES(@Db,CASE WHEN ERROR_NUMBER() IN(229,262,297,300,371,916) THEN 'DENIED_PERMISSION' WHEN ERROR_NUMBER()=1222 THEN 'TIMEOUT' ELSE 'ERROR_HANDLED' END,ERROR_NUMBER(),ERROR_MESSAGE());SET @Partial=1;IF @PrintMeldungen=1 BEGIN SET @Msg=FORMATMESSAGE(N'WARNUNG USP_QueryStoreForcedPlans [%s]: %s',@Db,ERROR_MESSAGE());RAISERROR(N'%s',10,1,@Msg) WITH NOWAIT;END;END CATCH;FETCH NEXT FROM [c] INTO @Db,@Compat;END;CLOSE [c];DEALLOCATE [c];END;
 UPDATE [r] SET [SourceType]='QUERY_STORE',[SourceObject]=N'sys.query_store_plan|sys.query_store_query_text',[CapturedAtUtc]=@Now,[EvidenceScope]='DATABASE_QUERY_PLAN',[QuerySqlTextCharacters]=[p].[OriginalCharacters],[QuerySqlTextBytes]=[p].[OriginalBytes],[QuerySqlTextIsTruncated]=[p].[IsTruncated],[QuerySqlText]=[p].[ProjectedValue],[QueryPlanStatus]=CASE WHEN @MitPlanXml=0 THEN 'NOT_REQUESTED' ELSE 'PENDING' END,[EvidenceLimit]=N'Gespeicherter Query-Store-Plan und aggregierte Metadaten; kein aktueller Ausführungsplan.' FROM [#QueryStoreForcedPlans_Result] [r] CROSS APPLY [monitor].[TVF_ProjectUnicodeText]([r].[QuerySqlText],@MaxSqlTextZeichen) [p];
 DECLARE @PlanDb int,@PlanQuery bigint,@PlanIdLocal bigint,@PlanText nvarchar(max),@PlanXml xml,@PlanStatus varchar(40),@PlanErr int,@PlanMsg nvarchar(2048);DECLARE [pc] CURSOR LOCAL FAST_FORWARD FOR SELECT [QueryStoreDatabaseId],[QueryId],[PlanId],[QueryPlanTextFallback] FROM [#QueryStoreForcedPlans_Result] WHERE @MitPlanXml=1;OPEN [pc];FETCH NEXT FROM [pc] INTO @PlanDb,@PlanQuery,@PlanIdLocal,@PlanText;WHILE @@FETCH_STATUS=0 BEGIN EXEC [monitor].[InternalParseXmlText] @XmlText=@PlanText,@XmlValue=@PlanXml OUTPUT,@StatusCode=@PlanStatus OUTPUT,@ErrorNumber=@PlanErr OUTPUT,@ErrorMessage=@PlanMsg OUTPUT;UPDATE [#QueryStoreForcedPlans_Result] SET [QueryPlanStatus]=@PlanStatus,[QueryPlanCharacters]=CASE WHEN @PlanText IS NULL THEN NULL ELSE CONVERT(bigint,LEN((@PlanText+NCHAR(1)) COLLATE Latin1_General_100_CI_AS_SC)-1) END,[QueryPlanBytes]=CONVERT(bigint,DATALENGTH(@PlanText)),[QueryPlan]=@PlanXml,[QueryPlanTextFallback]=CASE WHEN @PlanStatus IN('AVAILABLE','XML_EMPTY','SOURCE_NULL') THEN NULL ELSE @PlanText END WHERE [QueryStoreDatabaseId]=@PlanDb AND [QueryId]=@PlanQuery AND [PlanId]=@PlanIdLocal;IF @PlanStatus IN('XML_INVALID','XML_UNAVAILABLE_LIMIT') BEGIN INSERT [#QueryStoreForcedPlans_Errors] VALUES((SELECT TOP(1) [QueryStoreDatabaseName] FROM [#QueryStoreForcedPlans_Result] WHERE [QueryStoreDatabaseId]=@PlanDb),@PlanStatus,@PlanErr,@PlanMsg);SET @Partial=1;END;FETCH NEXT FROM [pc] INTO @PlanDb,@PlanQuery,@PlanIdLocal,@PlanText;END;CLOSE [pc];DEALLOCATE [pc];
 DECLARE @TruncatedValueCount bigint=0,@LargestRequiredCharacters bigint=NULL;SELECT @TruncatedValueCount=COUNT_BIG(*),@LargestRequiredCharacters=MAX([QuerySqlTextCharacters]) FROM [#QueryStoreForcedPlans_Result] WHERE [QuerySqlTextIsTruncated]=1;EXEC [monitor].[InternalEmitTruncationWarning] @TruncatedValueCount=@TruncatedValueCount,@ParameterName=N'@MaxSqlTextZeichen',@ParameterValue=@MaxSqlTextZeichen,@LargestRequiredCharacters=@LargestRequiredCharacters,@PrintMeldungen=@PrintMeldungen;
 SELECT @Count=COUNT_BIG(*) FROM [#QueryStoreForcedPlans_Result];SET @HasMore=CONVERT(bit,CASE WHEN @Limit<9223372036854775807 AND @Count>@Limit THEN 1 ELSE 0 END);IF @Partial=1 AND @Status='AVAILABLE' SET @Status='AVAILABLE_LIMITED';
 INSERT [#QueryStoreForcedPlans_Export] SELECT TOP(@Limit) * FROM [#QueryStoreForcedPlans_Result] ORDER BY CASE WHEN [LastForceFailureReason]<>0 THEN 0 ELSE 1 END,[LastExecutionTimeUtc] DESC;
 IF @Out<>'NONE' BEGIN SELECT N'USP_QueryStoreForcedPlans' [ModuleName],@Now [CollectionTimeUtc],@Status [StatusCode],@Partial [IsPartial],CASE WHEN @Count>@Limit THEN @Limit ELSE @Count END [ReturnedRowCount],@HasMore [HasMoreRows],@Error [ErrorMessage];IF @Out='RAW' SELECT * FROM [#QueryStoreForcedPlans_Export] ORDER BY CASE WHEN [LastForceFailureReason]<>0 THEN 0 ELSE 1 END,[LastExecutionTimeUtc] DESC;ELSE SELECT N'Erzwungener Query-Store-Plan' [Ergebnis],[QueryStoreDatabaseName] [Query-Store-Datenbank],[QueryId] [Query],[PlanId] [Plan],[LastForceFailureReasonDesc] [letzter Fehler],[ForceFailureCount] [Fehleranzahl],[LastExecutionTimeUtc] [letzte Ausführung],[QueryStoreDatabaseName] [Quelle],[QuerySqlText] [SQL-Text],[QueryPlan] [Plan-XML] FROM [#QueryStoreForcedPlans_Export] ORDER BY CASE WHEN [LastForceFailureReason]<>0 THEN 0 ELSE 1 END,[LastExecutionTimeUtc] DESC;SELECT * FROM [#QueryStoreForcedPlans_Errors] ORDER BY [DatabaseName];END;
 IF @JsonErzeugen=1 BEGIN DECLARE @Meta nvarchar(max)=(SELECT N'QueryStoreForcedPlans' [resultName],2 [schemaVersion],@Now [generatedAtUtc],@Status [statusCode],@MaxZeilen [requestedMaxRows],CASE WHEN @Count>@Limit THEN @Limit ELSE @Count END [returnedRows],@HasMore [hasMoreRows] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),@Data nvarchar(max)=(SELECT [QueryStoreDatabaseId],[QueryStoreDatabaseName],[QueryId],[PlanId],[QueryHash],[QueryPlanHash],[ObjectId],[ObjectName],[IsForcedPlan],[PlanForcingTypeDesc],[ForceFailureCount],[LastForceFailureReason],[LastForceFailureReasonDesc],[CountCompiles],[LastCompileStartTimeUtc],[LastExecutionTimeUtc],[EngineVersion],[CompatibilityLevel],[QuerySqlText],[QueryPlanTextFallback],[SourceType],[SourceObject],[CapturedAtUtc],[EvidenceScope],[QuerySqlTextCharacters],[QuerySqlTextBytes],[QuerySqlTextIsTruncated],[QueryPlanStatus],[QueryPlanCharacters],[QueryPlanBytes],CONVERT(nvarchar(max),[QueryPlan]) [QueryPlan],[EvidenceLimit] FROM [#QueryStoreForcedPlans_Export] ORDER BY CASE WHEN [LastForceFailureReason]<>0 THEN 0 ELSE 1 END,[LastExecutionTimeUtc] DESC FOR JSON PATH,INCLUDE_NULL_VALUES),@Warnings nvarchar(max)=(SELECT * FROM [#QueryStoreForcedPlans_Errors] ORDER BY [DatabaseName] FOR JSON PATH,INCLUDE_NULL_VALUES);SET @Json=CONCAT(N'{"meta":',COALESCE(@Meta,N'{}'),N',"forcedPlans":',COALESCE(@Data,N'[]'),N',"warnings":',COALESCE(@Warnings,N'[]'),N'}');END;
    IF @ConsoleResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalEmitConsoleResult]
              @SourceTable=N'#QueryStoreForcedPlans_Export'
            , @ResultLabel=N'QueryStoreForcedPlans'
            , @EmptyMessage=N'Keine fachlichen Ergebnisse';
    END;
    IF @TableResultRequested = 1
    BEGIN
        EXEC [monitor].[InternalWriteResultTable]
              @SourceTable = N'#QueryStoreForcedPlans_Export'
            , @TargetTable=@TableTarget
            , @ThrowOnError = 1;
    END;
END;
